void
treenode_navigate(const Arg *arg)
{
    Client *sel = selmon->sel;
    if (!sel || !sel->node)
        return;

    TreeNode *target = navigate_tree(sel->node, arg->i);

    if (target && target->client) {
        focus(target->client);
        restack(selmon);
    }
}

static TreeNode*
closest_leaf(int workspace)
{
    if (!workspace_roots[workspace])
        return NULL;

    TreeNode *queue[64];
    int front = -1;
    int rear = 0;

    queue[rear] = workspace_roots[workspace];
    rear++;

    while (!(front == rear - 1)) { // check if the queue is empty
        TreeNode *current = queue[front];
        front++;

        if (current->a == NULL && current->b == NULL)
            return current;

        if (current->a != NULL) {
            queue[rear] = current->a;
            rear++;
        }

        if (current->b != NULL) {
            queue[rear] = current->b;
            rear++;
        }
    }

    // Should never get here
    return NULL;
}

