static TreeNode*
closest_leaf(unsigned int workspace)
{
    if (!CHECK_WS_BOUNDS(workspace) || !workspace_roots[workspace - 1])
        return NULL;

    TreeNode *queue[64];
    int front = 0;
    int rear = 0;

    queue[rear++] = workspace_roots[workspace - 1];

    while (front < rear) {
        TreeNode *current = queue[front++];

        if (!current->a && !current->b)
            return current;

        assert(rear + (current->a != NULL) + (current->b != NULL) <= LENGTH(queue));
        if (current->a)
            queue[rear++] = current->a;
        if (current->b)
            queue[rear++] = current->b;
    }

    return NULL;
}

